__global__ void stable_softmax(const float* input, float* exponentials, float* probabilities, int n) {
  if (blockIdx.x != 0 || threadIdx.x != 0) {
    return;
  }
  float maxValue = input[0];
  for (int i = 1; i < n; i++) {
    if (input[i] > maxValue) {
      maxValue = input[i];
    }
  }
  float total = 0.0f;
  for (int i = 0; i < n; i++) {
    exponentials[i] = expf(input[i] - maxValue);
    total += exponentials[i];
  }
  for (int i = 0; i < n; i++) {
    probabilities[i] = exponentials[i] / total;
  }
}
